"""Tests for the two evolution-tree examples generated by
scripts/generate_mqtbench_evolution.py: Multiplier-8 and QFT-Adder-8.

These are genuinely differentiated examples (unlike GHZ-5/QFT-entangled-5,
their optimization and/or hardware-mapping branches produce measurably
different circuits) -- so, per the same rule established in Phase 4C,
these tests check structure and internal consistency only. They do NOT
assert which branch has more/fewer gates, since the whole point of the
underlying experiment is to observe that, not assume it.
"""

import json
from pathlib import Path

import networkx as nx
import pytest
from qiskit import qasm2

PROJECT_ROOT = Path(__file__).resolve().parent.parent
MQTBENCH_DIR = PROJECT_ROOT / "data" / "mqtbench"

EXAMPLES = [
    ("multiplier", 8),
    ("draper_qft_adder", 8),
]

DERIVED_VERSIONS = ["v2", "v3", "v4", "v5", "v6"]
ALL_VERSIONS = ["v1"] + DERIVED_VERSIONS


def _slug(benchmark: str, size: int) -> str:
    return f"{benchmark}_{size}"


def _root_circuit_id(benchmark: str, size: int) -> str:
    return f"qch:mqt:{benchmark}:{size}:v1"


def _load_evolution(benchmark: str, size: int) -> dict:
    path = MQTBENCH_DIR / "evolution" / _slug(benchmark, size) / f"{_slug(benchmark, size)}_evolution.json"
    return json.loads(path.read_text(encoding="utf-8"))


def _load_record(benchmark: str, size: int, version: str) -> dict:
    slug = _slug(benchmark, size)
    if version == "v1":
        path = MQTBENCH_DIR / "processed" / f"{slug}.json"
    else:
        path = MQTBENCH_DIR / "evolution" / slug / f"{slug}_{version}.json"
    return json.loads(path.read_text(encoding="utf-8"))


def _load_all_records(benchmark: str, size: int) -> dict[str, dict]:
    return {version: _load_record(benchmark, size, version) for version in ALL_VERSIONS}


def _build_graph(evolution: dict) -> nx.DiGraph:
    graph = nx.DiGraph()
    graph.add_nodes_from(node["circuit_id"] for node in evolution["nodes"])
    for edge in evolution["edges"]:
        graph.add_edge(edge["from"], edge["to"])
    return graph


@pytest.mark.parametrize("benchmark,size", EXAMPLES)
def test_evolution_has_exactly_6_nodes(benchmark, size):
    evolution = _load_evolution(benchmark, size)
    assert len(evolution["nodes"]) == 6


@pytest.mark.parametrize("benchmark,size", EXAMPLES)
def test_evolution_has_exactly_5_edges(benchmark, size):
    evolution = _load_evolution(benchmark, size)
    assert len(evolution["edges"]) == 5


@pytest.mark.parametrize("benchmark,size", EXAMPLES)
def test_root_matches_expected_circuit_id(benchmark, size):
    evolution = _load_evolution(benchmark, size)
    assert evolution["root"] == _root_circuit_id(benchmark, size)


@pytest.mark.parametrize("benchmark,size", EXAMPLES)
def test_parents_are_exactly_as_specified(benchmark, size):
    root_id = _root_circuit_id(benchmark, size)
    slug = _slug(benchmark, size)
    expected_parents = {
        "v2": root_id, "v3": root_id, "v4": root_id,
        "v5": f"qch:mqt:{benchmark}:{size}:v4", "v6": f"qch:mqt:{benchmark}:{size}:v4",
    }
    records = _load_all_records(benchmark, size)
    for version, expected_parent in expected_parents.items():
        assert records[version]["provenance"]["parent_version"] == expected_parent, slug


@pytest.mark.parametrize("benchmark,size", EXAMPLES)
def test_v2_v3_v4_are_siblings(benchmark, size):
    root_id = _root_circuit_id(benchmark, size)
    records = _load_all_records(benchmark, size)
    parents = {records[v]["provenance"]["parent_version"] for v in ("v2", "v3", "v4")}
    assert parents == {root_id}


@pytest.mark.parametrize("benchmark,size", EXAMPLES)
def test_v5_v6_are_siblings(benchmark, size):
    records = _load_all_records(benchmark, size)
    parents = {records[v]["provenance"]["parent_version"] for v in ("v5", "v6")}
    assert parents == {f"qch:mqt:{benchmark}:{size}:v4"}


@pytest.mark.parametrize("benchmark,size", EXAMPLES)
def test_every_derived_version_has_provenance(benchmark, size):
    records = _load_all_records(benchmark, size)
    for version in DERIVED_VERSIONS:
        provenance = records[version]["provenance"]
        for key in ("parent_version", "transformation", "tool", "tool_version", "parameters", "seed_transpiler"):
            assert key in provenance, f"{benchmark}_{size} {version} provenance missing '{key}'"


@pytest.mark.parametrize("benchmark,size", EXAMPLES)
def test_every_derived_version_has_evolution_metrics(benchmark, size):
    records = _load_all_records(benchmark, size)
    for version in DERIVED_VERSIONS:
        em = records[version]["evolution_metrics"]
        for key in (
            "swap_count", "cx_count", "two_qubit_gate_count", "multi_qubit_gate_count",
            "physical_layout", "layout_identity", "coupling_map", "topology", "circuit_fingerprint",
        ):
            assert key in em


@pytest.mark.parametrize("benchmark,size", EXAMPLES)
def test_seed_transpiler_42_is_recorded(benchmark, size):
    records = _load_all_records(benchmark, size)
    for version in DERIVED_VERSIONS:
        assert records[version]["provenance"]["seed_transpiler"] == 42
    for edge in _load_evolution(benchmark, size)["edges"]:
        assert edge["seed_transpiler"] == 42


@pytest.mark.parametrize("benchmark,size", EXAMPLES)
def test_v5_topology_is_linear_and_v6_is_ring(benchmark, size):
    v5 = _load_record(benchmark, size, "v5")
    v6 = _load_record(benchmark, size, "v6")
    assert v5["provenance"]["topology"] == "linear"
    assert v6["provenance"]["topology"] == "ring"
    assert isinstance(v5["provenance"]["coupling_map"], list) and v5["provenance"]["coupling_map"]
    assert isinstance(v6["provenance"]["coupling_map"], list) and v6["provenance"]["coupling_map"]


@pytest.mark.parametrize("benchmark,size", EXAMPLES)
def test_all_versions_have_expected_qubit_count(benchmark, size):
    records = _load_all_records(benchmark, size)
    for version in ALL_VERSIONS:
        assert records[version]["metrics"]["num_qubits"] == size


@pytest.mark.parametrize("benchmark,size", EXAMPLES)
def test_all_qasm_files_round_trip_parse(benchmark, size):
    slug = _slug(benchmark, size)
    root_path = MQTBENCH_DIR / "raw" / f"{slug}.qasm"
    circuit = qasm2.load(str(root_path), custom_instructions=qasm2.LEGACY_CUSTOM_INSTRUCTIONS)
    assert circuit.num_qubits == size

    for version in DERIVED_VERSIONS:
        qasm_path = MQTBENCH_DIR / "evolution" / slug / f"{slug}_{version}.qasm"
        circuit = qasm2.load(str(qasm_path), custom_instructions=qasm2.LEGACY_CUSTOM_INSTRUCTIONS)
        assert circuit.num_qubits == size


@pytest.mark.parametrize("benchmark,size", EXAMPLES)
def test_graph_is_a_dag(benchmark, size):
    graph = _build_graph(_load_evolution(benchmark, size))
    assert nx.is_directed_acyclic_graph(graph)


@pytest.mark.parametrize("benchmark,size", EXAMPLES)
def test_swap_cx_multi_qubit_counts_are_non_negative(benchmark, size):
    records = _load_all_records(benchmark, size)
    for version in DERIVED_VERSIONS:
        em = records[version]["evolution_metrics"]
        assert em["swap_count"] >= 0
        assert em["cx_count"] >= 0
        assert em["multi_qubit_gate_count"] >= 0


@pytest.mark.parametrize("benchmark,size", EXAMPLES)
def test_experiment_summary_exists_and_is_internally_consistent(benchmark, size):
    slug = _slug(benchmark, size)
    summary_path = MQTBENCH_DIR / "evolution" / slug / "experiment_summary.json"
    assert summary_path.exists()
    summary = json.loads(summary_path.read_text(encoding="utf-8"))

    assert summary["root_circuit"] == _root_circuit_id(benchmark, size)
    assert set(summary["results"]["metrics"].keys()) == set(ALL_VERSIONS)

    records = _load_all_records(benchmark, size)
    for version in ALL_VERSIONS:
        assert summary["results"]["metrics"][version]["gate_count"] == records[version]["metrics"]["gate_count"]


@pytest.mark.parametrize("benchmark,size", EXAMPLES)
def test_these_examples_are_genuinely_differentiated(benchmark, size):
    """Unlike GHZ-5/QFT-entangled-5, at least one hardware-mapping branch
    of these examples should differ from its sibling on some metric --
    otherwise they wouldn't add anything new to the demo. This does NOT
    assert which of v5/v6 is bigger, only that they are not identical."""
    records = _load_all_records(benchmark, size)
    v5_fp = records["v5"]["evolution_metrics"]["circuit_fingerprint"]
    v6_fp = records["v6"]["evolution_metrics"]["circuit_fingerprint"]
    assert v5_fp != v6_fp
